using FluentValidation;using Microsoft.EntityFrameworkCore;using SchoolERP.Application.Abstractions;using SchoolERP.Application.Common.Extensions;using SchoolERP.Application.Common.Pagination;using SchoolERP.Application.Exceptions;using SchoolERP.Application.Features.Schools;using SchoolERP.Domain.Entities;using SchoolERP.Domain.Enums;
namespace SchoolERP.Application.Features.Houses;
public sealed class HouseService(IApplicationDbContext db,ICurrentSchoolResolver current,IValidator<CreateHouseRequest> cv,IValidator<UpdateHouseRequest> uv,IValidator<ChangeHouseCodeRequest> ccv,TimeProvider clock):IHouseService{
 public async Task<PagedResult<HouseListItemDto>> ListAsync(GetHousesQuery r,CancellationToken ct=default){var sid=await current.ResolveAsync(ct);var q=db.Houses.AsNoTracking().Where(x=>x.SchoolId==sid).WhereIf(r.Status.HasValue,x=>x.Status==r.Status);if(!string.IsNullOrWhiteSpace(r.Search)){var t=r.Search.Trim().ToLower();q=q.Where(x=>x.Name.ToLower().Contains(t)||x.Code.ToLower().Contains(t)||(x.ShortName!=null&&x.ShortName.ToLower().Contains(t))||(x.Motto!=null&&x.Motto.ToLower().Contains(t)));}var d=string.Equals(r.SortDirection,"desc",StringComparison.OrdinalIgnoreCase);q=(r.SortBy?.ToLowerInvariant(),d) switch{("name",false)=>q.OrderBy(x=>x.Name),("name",true)=>q.OrderByDescending(x=>x.Name),("code",false)=>q.OrderBy(x=>x.Code),("code",true)=>q.OrderByDescending(x=>x.Code),("status",false)=>q.OrderBy(x=>x.Status),("status",true)=>q.OrderByDescending(x=>x.Status),("createdat",false)=>q.OrderBy(x=>x.CreatedAt),("createdat",true)=>q.OrderByDescending(x=>x.CreatedAt),("displayorder",true)=>q.OrderByDescending(x=>x.DisplayOrder).ThenBy(x=>x.Name),_=>q.OrderBy(x=>x.DisplayOrder).ThenBy(x=>x.Name)};return await q.Select(x=>new HouseListItemDto(x.Id,x.Name,x.Code,x.ShortName,x.ColorHex,x.DisplayOrder,x.Status,x.CreatedAt,x.UpdatedAt)).ToPagedResultAsync(new(r.PageNumber,r.PageSize),ct);}
 public async Task<HouseDetailsDto?> GetAsync(Guid id,CancellationToken ct=default){var sid=await current.ResolveAsync(ct);return await db.Houses.AsNoTracking().Where(x=>x.Id==id&&x.SchoolId==sid).Select(x=>new HouseDetailsDto(x.Id,x.Name,x.Code,x.ShortName,x.ColorHex,x.DisplayOrder,x.Motto,x.Description,x.Status,x.ActivatedAt,x.DeactivatedAt,x.ArchivedAt,x.CreatedAt,x.UpdatedAt)).SingleOrDefaultAsync(ct);}
 public async Task<HouseDetailsDto> CreateAsync(CreateHouseRequest r,CancellationToken ct=default){await cv.ValidateAndThrowAsync(r,ct);var sid=await current.ResolveAsync(ct);var school=await MutableSchool(sid,ct);await Unique(sid,r.Code,r.Name,null,ct);var x=House.Create(school.TenantId,sid,r.Name,r.Code,r.ShortName,r.ColorHex,r.DisplayOrder,r.Motto,r.Description,Now());db.Houses.Add(x);await db.SaveChangesAsync(ct);return(await GetAsync(x.Id,ct))!;}
 public async Task<HouseDetailsDto?> UpdateAsync(Guid id,UpdateHouseRequest r,CancellationToken ct=default){await uv.ValidateAndThrowAsync(r,ct);var x=await Write(id,ct);if(x is null)return null;await MutableSchool(x.SchoolId,ct);await Unique(x.SchoolId,x.Code,r.Name,id,ct);x.UpdateDetails(r.Name,r.ShortName,r.ColorHex,r.DisplayOrder,r.Motto,r.Description,Now());await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}
 public async Task<HouseDetailsDto?> ChangeCodeAsync(Guid id,ChangeHouseCodeRequest r,CancellationToken ct=default){await ccv.ValidateAndThrowAsync(r,ct);var x=await Write(id,ct);if(x is null)return null;await MutableSchool(x.SchoolId,ct);await Unique(x.SchoolId,r.Code,x.Name,id,ct);x.ChangeCode(r.Code,Now());await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}
 public async Task<HouseDetailsDto?> ActivateAsync(Guid id,CancellationToken ct=default){var x=await Write(id,ct);if(x is null)return null;var school=await db.Schools.AsNoTracking().SingleAsync(s=>s.Id==x.SchoolId,ct);if(school.Status!=SchoolStatus.Active)throw new ParentNotOperationalException("House.SchoolMustBeActive");x.Activate(Now());await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}public Task<HouseDetailsDto?> DeactivateAsync(Guid id,CancellationToken ct=default)=>Change(id,x=>x.Deactivate(Now()),ct);public Task<HouseDetailsDto?> ArchiveAsync(Guid id,CancellationToken ct=default)=>Change(id,x=>x.Archive(Now()),ct);
 private async Task<HouseDetailsDto?> Change(Guid id,Action<House> action,CancellationToken ct){var x=await Write(id,ct);if(x is null)return null;await MutableSchool(x.SchoolId,ct);action(x);await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}private async Task<House?> Write(Guid id,CancellationToken ct){var sid=await current.ResolveAsync(ct);return await db.Houses.SingleOrDefaultAsync(x=>x.Id==id&&x.SchoolId==sid,ct);}private async Task<School> MutableSchool(Guid id,CancellationToken ct){var x=await db.Schools.AsNoTracking().SingleAsync(s=>s.Id==id,ct);if(x.Status is SchoolStatus.Suspended or SchoolStatus.Archived)throw new ParentNotOperationalException("House.SchoolUnavailable");return x;}private async Task Unique(Guid sid,string code,string name,Guid? except,CancellationToken ct){var c=House.NormalizeCode(code);var n=name.Trim().ToLower();if(await db.Houses.AsNoTracking().AnyAsync(x=>x.SchoolId==sid&&x.Code==c&&(!except.HasValue||x.Id!=except),ct))throw new HouseCodeConflictException();if(await db.Houses.AsNoTracking().AnyAsync(x=>x.SchoolId==sid&&x.Name.ToLower()==n&&(!except.HasValue||x.Id!=except),ct))throw new HouseNameConflictException();}private DateTime Now()=>clock.GetUtcNow().UtcDateTime;}
